import { test, expect } from "@playwright/test";
import path from "node:path";
const password = process.env.DEMO_PASSWORD;
if (!password)
  throw new Error(
    "Set DEMO_PASSWORD to the password generated by backend setup before running browser tests.",
  );
const stamp = Date.now();
const appErrors = new WeakMap();
test.beforeEach(async ({ page }) => {
  const errors = [];
  appErrors.set(page, errors);
  page.on("pageerror", (e) => errors.push(e.message));
});
test.afterEach(async ({ page }) => {
  expect(appErrors.get(page)).toEqual([]);
});
async function login(
  page,
  email = "customer1@homeloan.demo",
  secret = password,
) {
  await page.goto("/login");
  await page.getByLabel(/^Email address(?: \*)?$/).fill(email);
  await page.getByLabel(/^Password(?: \*)?$/).fill(secret);
  await page.getByRole("button", { name: "Log in to your workspace" }).click();
  await expect(page).toHaveURL(/\/app/);
  await expect(
    page.getByRole("button", { name: "Log out", exact: true }),
  ).toBeAttached();
}
async function logout(page) {
  await page.getByRole("button", { name: "Log out", exact: true }).click();
  await expect(page).toHaveURL(/\/login/);
}
async function decision(page, button, remarks) {
  await page.getByRole("button", { name: button, exact: true }).click();
  const dialog = page.getByRole("dialog");
  await dialog.getByLabel(/^Decision remarks(?: \*)?$/).fill(remarks);
  await dialog
    .getByRole("button", {
      name:
        button === "Record disbursement"
          ? "Record demo disbursement"
          : button === "Request documents"
            ? "Request additional documents"
            : button,
      exact: true,
    })
    .click();
  await expect(dialog).not.toBeVisible();
  await expect(
    page.getByRole("button", { name: "Refresh application" }),
  ).toBeVisible();
}

test("public pages, responsive mobile layout and offline recovery", async ({
  page,
}) => {
  await page.goto("/");
  await expect(
    page.getByRole("heading", {
      name: "A little clarity. A place to call home.",
    }),
  ).toBeVisible();
  if (process.env.SCREENSHOT_DIR)
    await page.screenshot({
      path: path.join(process.env.SCREENSHOT_DIR, "nestwell-home.png"),
      fullPage: true,
    });
  await page.goto("/products");
  await expect(
    page.getByRole("heading", { name: "Standard Home Loan", exact: true }),
  ).toBeVisible();
  await page.goto("/about");
  await expect(
    page.getByRole("heading", { name: "Home loans, with more clarity." }),
  ).toBeVisible();
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/");
  await page.getByRole("button", { name: "Toggle navigation" }).click();
  await page.getByRole("link", { name: "Loan products", exact: true }).click();
  await expect(
    page.getByRole("heading", { name: "Standard Home Loan", exact: true }),
  ).toBeVisible();
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= window.innerWidth + 1,
    ),
  ).toBe(true);
  if (process.env.SCREENSHOT_DIR)
    await page.screenshot({
      path: path.join(
        process.env.SCREENSHOT_DIR,
        "nestwell-mobile-products.png",
      ),
      fullPage: true,
    });
  await page.route("**/api/loan-products", (route) => route.abort("failed"));
  await page.reload();
  await expect(page.getByRole("alert")).toContainText("could not reach");
  await page.unroute("**/api/loan-products");
  await page.getByRole("button", { name: "Try again" }).click();
  await expect(
    page.getByRole("heading", { name: "Standard Home Loan", exact: true }),
  ).toBeVisible();
});

test("registration, profile update, role guard and session expiry", async ({
  page,
}) => {
  await page.goto("/register");
  await page.getByLabel(/^Full name(?: \*)?$/).fill("Browser Demo Customer");
  await page.getByLabel(/^Mobile number(?: \*)?$/).fill("9000000099");
  await page.getByLabel(/^Date of birth(?: \*)?$/).fill("1995-04-15");
  await page.getByLabel(/^Address(?: \*)?$/).fill("12 Fictional Demo Street");
  await page.getByLabel(/^Monthly income \(₹\)(?: \*)?$/).fill("95000");
  await page
    .getByLabel(/^Email address(?: \*)?$/)
    .fill(`browser-${stamp}@example.test`);
  await page.getByLabel(/^Password(?: \*)?$/).fill(password);
  await page.getByRole("button", { name: "Create customer account" }).click();
  await expect(page).toHaveURL(/\/app$/);
  await expect(
    page.getByRole("heading", { name: "Hello, Browser." }),
  ).toBeVisible();
  await page.getByRole("link", { name: "My profile", exact: true }).click();
  await page.getByLabel(/^Full name(?: \*)?$/).fill("Updated Browser Demo");
  await page.getByRole("button", { name: "Save changes" }).click();
  await expect(page.getByRole("status")).toContainText(
    "profile has been updated",
  );
  await page.reload();
  await expect(page.getByLabel(/^Full name(?: \*)?$/)).toHaveValue(
    "Updated Browser Demo",
  );
  await page.goto("/app/admin/customers");
  await expect(page).toHaveURL(/\/app$/);
  await expect(
    page.getByRole("heading", { name: "Hello, Updated." }),
  ).toBeVisible();
  await page.evaluate(() => {
    const s = JSON.parse(sessionStorage.getItem("nestwell.session.v1"));
    s.expiresAt = Date.now() - 1;
    sessionStorage.setItem("nestwell.session.v1", JSON.stringify(s));
  });
  await page.reload();
  await expect(page).toHaveURL(/\/login/);
});

test("eligibility, real direct CORS preflight and dashboard", async ({
  page,
}) => {
  await login(page);
  await expect(
    page.getByRole("heading", { name: "Hello, Aarav." }),
  ).toBeVisible();
  if (process.env.SCREENSHOT_DIR)
    await page.screenshot({
      path: path.join(process.env.SCREENSHOT_DIR, "nestwell-dashboard.png"),
      fullPage: true,
    });
  await page
    .getByRole("link", { name: "Eligibility calculator", exact: true })
    .click();
  await page.getByLabel(/^Monthly income \(₹\)(?: \*)?$/).fill("100000");
  await page.getByLabel(/^Existing monthly EMIs \(₹\)(?: \*)?$/).fill("5000");
  await page.getByRole("button", { name: "Calculate my estimate" }).click();
  await expect(
    page.getByText("Meets preliminary criteria", { exact: true }),
  ).toBeVisible();
  await expect(page.getByText("₹26,034.70", { exact: true })).toBeVisible();
  await page.getByLabel(/^Monthly income \(₹\)(?: \*)?$/).fill("10000");
  await expect(
    page.getByText("Meets preliminary criteria", { exact: true }),
  ).not.toBeVisible();
  await page.getByRole("button", { name: "Calculate my estimate" }).click();
  await expect(
    page.getByText("Does not meet preliminary criteria", { exact: true }),
  ).toBeVisible();
  const direct = await page.evaluate(async () => {
    const s = JSON.parse(sessionStorage.getItem("nestwell.session.v1"));
    const response = await fetch(
      "http://localhost:8080/api/eligibility/check",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${s.accessToken}`,
          "Idempotency-Key": "cors-check-001",
        },
        body: JSON.stringify({
          monthlyIncome: 100000,
          existingEmi: 5000,
          requestedLoanAmount: 3000000,
          tenureMonths: 240,
          interestRate: 8.5,
        }),
      },
    );
    return { status: response.status, data: await response.json() };
  });
  expect(direct.status).toBe(200);
  expect(direct.data.eligible).toBe(true);
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/app");
  await expect(
    page.getByRole("heading", { name: "Hello, Aarav." }),
  ).toBeVisible();
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= window.innerWidth + 1,
    ),
  ).toBe(true);
  await page.getByRole("button", { name: "Open navigation" }).click();
  await page
    .getByRole("link", { name: "My applications", exact: true })
    .click();
  await expect(
    page.getByRole("heading", { name: "Your plans, in progress." }),
  ).toBeVisible();
});

test("complete customer → officer → admin workflow with documents and ownership checks", async ({
  page,
}) => {
  await login(page);
  await page
    .getByRole("link", { name: "New application", exact: true })
    .click();
  await page.getByLabel(/^Loan product(?: \*)?$/).selectOption("1");
  await page
    .getByLabel(/^Requested loan amount \(₹\)(?: \*)?$/)
    .fill("4201234");
  await page.getByLabel(/^Loan tenure \(months\)(?: \*)?$/).fill("240");
  await page.getByRole("button", { name: "Continue", exact: true }).click();
  await page.getByLabel(/^Monthly income \(₹\)(?: \*)?$/).fill("120000");
  await page.getByLabel(/^Existing monthly EMIs \(₹\)(?: \*)?$/).fill("5000");
  await page.getByRole("button", { name: "Continue", exact: true }).click();
  await page.getByRole("checkbox").check();
  const submitted = page.waitForResponse(
    (r) =>
      r.url().endsWith("/api/loan-applications") &&
      r.request().method() === "POST",
  );
  await page
    .getByRole("button", { name: "Submit application", exact: true })
    .click();
  const data = await (await submitted).json();
  await expect(page).toHaveURL(
    new RegExp(`/app/applications/${data.id}\\?tab=documents`),
  );
  await expect(
    page.getByRole("heading", { name: "Your document checklist" }),
  ).toBeVisible();
  const sample =
    process.env.SAMPLE_DOCUMENT ||
    path.resolve("samples/fictional-demo-document.pdf");
  for (const label of [
    "Identity proof",
    "Address proof",
    "Income proof",
    "Bank statement",
    "Property document",
  ]) {
    const card = page
      .getByRole("article")
      .filter({ has: page.getByRole("heading", { name: label, exact: true }) });
    await card.getByRole("button", { name: "Upload", exact: true }).click();
    const dialog = page.getByRole("dialog");
    await dialog.getByLabel(/^Choose document(?: \*)?$/).setInputFiles(sample);
    await dialog
      .getByRole("button", { name: "Upload document", exact: true })
      .click();
    await expect(dialog).not.toBeVisible();
    await expect(
      page.getByRole("heading", { name: "Your document checklist" }),
    ).toBeVisible();
    await expect(
      card.getByText("Pending review", { exact: true }),
    ).toBeVisible();
  }
  const downloadEvent = page.waitForEvent("download");
  await page
    .getByRole("button", { name: "Download", exact: true })
    .first()
    .click();
  expect((await downloadEvent).suggestedFilename()).toBe(
    "fictional-demo-document.pdf",
  );
  await logout(page);
  await login(
    page,
    `officer${data.assignedOfficerId === 2 ? "1" : "2"}@homeloan.demo`,
  );
  await page.goto(`/app/applications/${data.id}?tab=documents`);
  await decision(page, "Start review", "Browser test: review started");
  await expect(
    page.getByRole("button", { name: "Approve application", exact: true }),
  ).toBeDisabled();
  for (const label of [
    "Identity proof",
    "Address proof",
    "Income proof",
    "Bank statement",
    "Property document",
  ]) {
    const card = page
      .getByRole("article")
      .filter({ has: page.getByRole("heading", { name: label, exact: true }) });
    await card.getByRole("button", { name: "Review", exact: true }).click();
    const dialog = page.getByRole("dialog");
    await dialog
      .getByLabel(/^Verification remarks(?: \*)?$/)
      .fill("Fictional document verified in browser test");
    await dialog.getByRole("button", { name: "Save verification" }).click();
    await expect(dialog).not.toBeVisible();
    await expect(
      page.getByRole("heading", { name: "Your document checklist" }),
    ).toBeVisible();
    await expect(card.getByText("Verified", { exact: true })).toBeVisible();
  }
  await expect(
    page.getByRole("button", { name: "Approve application", exact: true }),
  ).toBeEnabled();
  await decision(
    page,
    "Approve application",
    "Browser test: all documents checked",
  );
  await expect(
    page.getByRole("button", { name: "Record sanction", exact: true }),
  ).toHaveCount(0);
  await logout(page);
  await login(page, "admin@homeloan.demo");
  await page.goto(`/app/applications/${data.id}`);
  await decision(page, "Record sanction", "Browser test: sanction recorded");
  await decision(
    page,
    "Record disbursement",
    "Browser test: demo disbursement recorded",
  );
  await page
    .getByRole("button", { name: "Activity & history", exact: true })
    .click();
  await expect(
    page.getByText("Browser test: demo disbursement recorded", { exact: true }),
  ).toBeVisible();
  await page.reload();
  await expect(
    page.getByText("Browser test: demo disbursement recorded", { exact: true }),
  ).toBeVisible();
  await logout(page);
  await login(page, "customer2@homeloan.demo");
  await page.goto(`/app/applications/${data.id}`);
  await expect(page.getByRole("alert")).toContainText("Access denied");
});

test("admin product, officer, customer management and accessible dialogs", async ({
  page,
}) => {
  await login(page, "admin@homeloan.demo");
  await page.getByRole("link", { name: "Loan products", exact: true }).click();
  await page
    .getByRole("button", { name: "Create product", exact: true })
    .click();
  let dialog = page.getByRole("dialog");
  await dialog
    .getByLabel(/^Product name(?: \*)?$/)
    .fill(`Browser product ${stamp}`);
  await dialog
    .getByLabel(/^Description(?: \*)?$/)
    .fill("Fictional product for browser integration verification.");
  await dialog
    .getByRole("button", { name: "Create product", exact: true })
    .click();
  await expect(dialog).not.toBeVisible();
  const product = page.getByRole("article").filter({
    has: page.getByRole("heading", {
      name: `Browser product ${stamp}`,
      exact: true,
    }),
  });
  await expect(product).toBeVisible();
  await product.getByRole("button", { name: "Edit product" }).click();
  dialog = page.getByRole("dialog");
  await dialog.getByRole("checkbox").uncheck();
  await dialog.getByRole("button", { name: "Save product" }).click();
  await expect(dialog).not.toBeVisible();
  await expect(product.getByText("Inactive", { exact: true })).toBeVisible();
  await page.getByRole("link", { name: "Loan officers", exact: true }).click();
  await page.getByRole("button", { name: "Add loan officer" }).click();
  dialog = page.getByRole("dialog");
  await dialog.getByLabel(/^Full name(?: \*)?$/).fill("Browser Test Officer");
  await dialog
    .getByLabel(/^Email address(?: \*)?$/)
    .fill(`officer-${stamp}@example.test`);
  await dialog.getByLabel(/^Password(?: \*)?$/).fill(password);
  await dialog.getByRole("button", { name: "Create officer" }).click();
  await expect(dialog).not.toBeVisible();
  const row = page
    .getByRole("row")
    .filter({ hasText: `officer-${stamp}@example.test` });
  await row.getByRole("button", { name: "Edit officer" }).click();
  dialog = page.getByRole("dialog");
  await dialog
    .getByRole("checkbox", { name: "Account enabled", exact: true })
    .uncheck();
  await dialog.getByRole("button", { name: "Save officer" }).click();
  await expect(dialog).not.toBeVisible();
  await expect(row.getByText("Disabled", { exact: true })).toBeVisible();
  await page.getByRole("link", { name: "Customers", exact: true }).click();
  await page
    .getByRole("button", { name: "Edit Neel Demo", exact: true })
    .click();
  dialog = page.getByRole("dialog");
  await dialog
    .getByLabel(/^Address(?: \*)?$/)
    .fill("Updated fictional address from browser test");
  await dialog.getByRole("button", { name: "Save customer" }).click();
  await expect(dialog).not.toBeVisible();
  await page
    .getByRole("button", { name: "Disable Neel Demo", exact: true })
    .click();
  await expect(page.getByRole("dialog")).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(page.getByRole("dialog")).not.toBeVisible();
});

test("assignment, officer access, remarks, additional documents and rejection", async ({
  page,
}) => {
  await login(page, "admin@homeloan.demo");
  await page.goto("/app/applications/1");
  await page
    .getByRole("button", { name: "Reassign officer", exact: true })
    .click();
  let dialog = page.getByRole("dialog");
  await dialog.getByLabel(/^Loan officer(?: \*)?$/).selectOption("3");
  await dialog.getByRole("button", { name: "Save assignment" }).click();
  await expect(dialog).not.toBeVisible();
  await page.getByRole("button", { name: "Add remark", exact: true }).click();
  dialog = page.getByRole("dialog");
  await dialog
    .getByRole("textbox")
    .fill("Browser check: assigned for further review.");
  await dialog.getByRole("button", { name: "Add remark", exact: true }).click();
  await expect(dialog).not.toBeVisible();
  await logout(page);
  await login(page, "officer1@homeloan.demo");
  await page.goto("/app/applications/1");
  await expect(page.getByRole("alert")).toContainText("Access denied");
  await logout(page);
  await login(page, "officer2@homeloan.demo");
  await page.goto("/app/applications/1");
  await decision(
    page,
    "Request documents",
    "Please upload a clearer fictional identity document.",
  );
  await logout(page);
  await login(page);
  await page.goto("/app/applications/1?tab=history");
  await expect(
    page.getByText("Please upload a clearer fictional identity document.", {
      exact: true,
    }),
  ).toBeVisible();
  await expect(
    page.getByText("Browser check: assigned for further review.", {
      exact: true,
    }),
  ).toBeVisible();
  await page.getByRole("button", { name: "Documents", exact: true }).click();
  const card = page
    .getByRole("article")
    .filter({
      has: page.getByRole("heading", { name: "Identity proof", exact: true }),
    });
  await card.getByRole("button", { name: "Upload", exact: true }).click();
  dialog = page.getByRole("dialog");
  await dialog
    .getByLabel("Choose document")
    .setInputFiles({
      name: "invalid.txt",
      mimeType: "text/plain",
      buffer: Buffer.from("Fictional test"),
    });
  await dialog
    .getByRole("button", { name: "Upload document", exact: true })
    .click();
  await expect(dialog.getByRole("alert")).toContainText("PDF");
  await dialog
    .getByLabel("Choose document")
    .setInputFiles(
      process.env.SAMPLE_DOCUMENT ||
        path.resolve("samples/fictional-demo-document.pdf"),
    );
  await dialog
    .getByRole("button", { name: "Upload document", exact: true })
    .click();
  await expect(dialog).not.toBeVisible();
  await expect(card.getByText("Pending review", { exact: true })).toBeVisible();
  await logout(page);
  await login(page, "officer2@homeloan.demo");
  await page.goto("/app/applications/1?tab=documents");
  await decision(page, "Start review", "Reviewing requested evidence.");
  await card.getByRole("button", { name: "Review", exact: true }).click();
  dialog = page.getByRole("dialog");
  await dialog.getByLabel("Verification decision").selectOption("REJECTED");
  await dialog
    .getByLabel(/^Verification remarks(?: \*)?$/)
    .fill("Fictional evidence does not meet demo criteria.");
  await dialog.getByRole("button", { name: "Save verification" }).click();
  await expect(dialog).not.toBeVisible();
  await expect(card.getByText("Rejected", { exact: true })).toBeVisible();
  await decision(
    page,
    "Reject application",
    "Demo rejection after document review.",
  );
  await expect(
    page.getByRole("button", { name: "Approve application", exact: true }),
  ).toHaveCount(0);
  await logout(page);
  await login(page, "admin@homeloan.demo");
  await page.goto("/app/applications/1");
  await expect(
    page.getByText("This application was rejected and is closed.", {
      exact: false,
    }),
  ).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Record disbursement", exact: true }),
  ).toHaveCount(0);
});
